mapper.select:
select distinct sm.* from sys_role_menu srm left join sys_menu sm on srm.menu_id = sm.id left join sys_user_role sur on srm.role_id = sur.role_id where sur.user_id=#{userId} and sm.deleted=0 and sm.status=1
AND sm.type=#{type}
order by sm.sort_no

select distinct sm.* from sys_role_menu srm left join sys_menu sm on srm.menu_id = sm.id left join sys_user_role sur on srm.role_id = sur.role_id where sur.user_id=#{userId} and sm.deleted=0 and sm.status=1 and sm.project_code=#{projectCode}
AND sm.type=#{type}
order by sm.sort_no

select distinct sm.* 
from sys_role_menu srm
left join sys_menu sm on srm.menu_id = sm.id
left join sys_user_role sur on srm.role_id = sur.role_id
inner join sys_tenant_menu stm on sm.id = stm.menu_id
where sur.user_id = #{userId} 
  and sm.deleted = 0 
  and sm.status = 1
  and srm.tenant_id = #{tenantId}
  and stm.tenant_id = #{tenantId}

    and sm.type = #{type}

order by sm.sort_no

select distinct sm.* 
from sys_role_menu srm
left join sys_menu sm on srm.menu_id = sm.id
left join sys_user_role sur on srm.role_id = sur.role_id
inner join sys_tenant_menu stm on sm.id = stm.menu_id
where sur.user_id = #{userId} 
  and sm.deleted = 0 
  and sm.status = 1
  and sm.project_code = #{projectCode}
  and srm.tenant_id = #{tenantId}
  and stm.tenant_id = #{tenantId}

    and sm.type = #{type}

order by sm.sort_no
